// Shields in two rows, the way a testudo is drawn up.
import * as angular from "angular";

class ShieldWallController implements angular.IController {
    static $inject = [ "armoryService" ];

    shields: any;
    front: any;
    rear: any;

    constructor(private armoryService: any) {}

    $onInit(): void {
        this.front = this.armoryService.frontRow(this.shields);
        this.rear = this.armoryService.rearRow(this.shields);
    }
}

angular.module("castra.core")
    .component("shieldWall", {
        templateUrl: "app/ajs/features/armory/components/shield-wall.html",
        controller: ShieldWallController,
        bindings: { shields: "<" }
    });

