// A count with plus and minus buttons.
import * as angular from "angular";

class GladiusCounterController implements angular.IController {
    static $inject: string[] = [];

    count: any;
    label: any;

    step(delta: any): void {
        this.count = Math.max(0, this.count + delta);
    }
}

angular.module("castra.core")
    .component("gladiusCounter", {
        templateUrl: "app/ajs/features/armory/components/gladius-counter.html",
        controller: GladiusCounterController,
        bindings: { count: "<", label: "@?" }
    });

