// One line that sums the rations up.
angular.module("castra.core")
    .component("rationSummary", {
        template: "<p class=\"ration-summary\">{{ $ctrl.rations.length }} rations, {{ $ctrl.weight() | rationUnit:'modius' }} in store</p>",
        controller: RationSummaryController,
        bindings: { rations: "<" }
    });

