// AngularJS services that Angular code still needs. Each one is read from the AngularJS injector under its registered name.

export abstract class LegacyReports {
    abstract latest(): Promise<unknown[]>;
}

export abstract class LegacyLegions {
    abstract list(): Promise<unknown[]>;
}

export abstract class LegacyState {
    abstract go(state: string, params?: object): void;
}

export const ajsProviders = [
    { provide: LegacyReports, useFactory: (i: any) => i.get("legacyReports"), deps: [ "$injector" ] },
    { provide: LegacyLegions, useFactory: (i: any) => i.get("legionService"), deps: [ "$injector" ] },
    { provide: LegacyState, useFactory: (i: any) => i.get("$state"), deps: [ "$injector" ] }
];

