// The patrol log, the night watches and the tents.
angular.module("castra.core")
    .service("patrolService", PatrolService);

PatrolService.$inject = [ "$http", "$injector" ];

function PatrolService ($http, $injector) {
    var service = this;
    var entries = [];

    service.entries = function () {
        return $http.get("/api/patrols").then(function (response) {
            entries = response.data;
            return entries;
        });
    };

    service.cachedEntries = function () {
        return entries;
    };

    service.dismiss = function (entryId) {
        return $http.delete("/api/patrols/" + entryId);
    };

    service.watches = function () {
        return [ { id: 1, name: "Prima vigilia", start: "18:00", end: "21:00" } ];
    };

    service.tents = function () {
        return $http.get("/api/tents").then(function (response) {
            return response.data;
        });
    };

    service.rowsOf = function (tents) {
        var rows = [];
        for (var index = 0; index < tents.length; index += 8) {
            rows.push(tents.slice(index, index + 8));
        }
        return rows;
    };

    service.firstTent = function () {
        return { number: 1, occupants: 0, capacity: 8 };
    };

    service.campTime = function () {
        // Looked up when it is needed: the clock starts its timer as soon as it is created.
        return $injector.get("campClock").now();
    };
}

